Find the zeroes and the value of $f(0)$ from the graph of $y=f(x)$.
[tikz]
\begin{tikzpicture}[x=8mm,y=4mm]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[->,black] (-2,0)--(4.2,0) node[right,font=\fontsize{10}{12}\selectfont] {$x$};
\draw[->,black] (0,-4.7)--(0,3.2) node[above,font=\fontsize{10}{12}\selectfont] {$y$};
\foreach \x in {-1,1,2,3,4} {\draw[black] (\x,0.12)--(\x,-0.12);\path (\x,-0.15) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\foreach \y in {-4,-3,-2,-1,1,2} {\draw[black] (-0.08,\y)--(0.08,\y);\path (-0.1,\y) node[left,font=\fontsize{8.5}{10}\selectfont] {$\y$};}
\draw[<->,curveBlue,thick,domain=-1.6:3.6,samples=81] plot (\x,{(\x)^2-2*\x-3});
\end{tikzpicture}
[/tikz]
